import asyncio, json
import pathlib
from playwright.async_api import async_playwright
PROTO = pathlib.Path(__file__).with_name('BRAC_Nirapatta_Prototype.html').resolve().as_uri()
R=[]
def check(id_, name, cond, detail=''):
    R.append((id_, name, 'PASS' if cond else 'FAIL', detail)); 
async def kpis(pg):
    await pg.click('[data-wact="page"][data-v="overview"]')
    return await pg.evaluate("[...document.querySelectorAll('.kpi .v')].map(e=>+e.textContent)")
