        await pg.click('[data-act="go"][data-to="home"]'); check('F-07c','Latest Advisory card updated on phone', 'Heavy rain in Dhaka' in await pg.inner_text('.advisory'))
        await pg.click('[data-act="go"][data-to="alerts"]'); await pg.wait_for_timeout(1700)
        check('F-07d','Opening Security Alerts clears badge', (await S("D.unreadFor('102934')"))==0)
        # --- language
        await pg.click('[data-act="lang"]'); txt = await pg.inner_text('#screen')
